export const BRANCHES: Branch[] = RAW.map(([b]) => b)

export const SKILLS: Skill[] = RAW.flatMap(([b, raws]) =>
  raws.map(([id, name, tier, lane, requires, what, cues, challenges]) => ({
    id, name, branch: b.id, tier, lane, requires, what, cues: split(cues), challenges: split(challenges),
  })),
)

export const BY_ID = new Map(SKILLS.map((s) => [s.id, s]))
export const BRANCH_BY_ID = new Map(BRANCHES.map((b) => [b.id, b]))
